    s += step(compare, unpackRGBAToDepth(texture2D(tBeamShadow, sc.xy + vec2( 0.000,  1.000) * r)));
    s += step(compare, unpackRGBAToDepth(texture2D(tBeamShadow, sc.xy + vec2( 0.000, -1.000) * r)));
